schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "faion://ai-pre-screen-bias-guardrails/output.schema.json",
  "title": "AI pre-screen bias guardrail spec",
  "type": "object",
  "required": [
    "role_title", "candidate_jurisdictions", "redaction", "rubric", "proxy_review",
    "calibration", "adverse_impact", "human_of_record", "legal", "audit_log",
    "pinned_tuple", "evidence"
  ],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "date": {"type": "string", "format": "date", "pattern": "^\\d{4}-\\d{2}-\\d{2}$"},
    "sha256": {"type": "string", "pattern": "^sha256:[0-9a-f]{64}$"},
    "version": {"type": "string", "pattern": "^\\d+\\.\\d+(\\.\\d+)?$"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "role_title": {"type": "string", "minLength": 3},
    "candidate_jurisdictions": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 2}},
    "redaction": {
      "type": "object",
      "required": ["version", "stripped_attributes", "unit_tested", "fixture_set_path", "human_sample_inspected_per_release"],
      "additionalProperties": false,
      "properties": {
        "version": {"$ref": "#/definitions/version"},
        "stripped_attributes": {
          "type": "array",
          "minItems": 10,
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["name", "photo", "email-handle", "date-of-birth-and-age", "graduation-years", "address-below-city", "gender-markers-and-pronouns", "nationality-and-visa-status", "marital-and-parental-status", "protected-class-associations"]}
        },
        "unit_tested": {"type": "boolean", "const": true},
        "fixture_set_path": {"type": "string", "minLength": 3},
        "human_sample_inspected_per_release": {"type": "boolean", "const": true},
        "sample_size_per_release": {"type": "integer", "minimum": 1}
      }
    },
    "rubric": {
      "type": "object",
      "required": ["version", "hash", "written_before_first_score", "criteria"],
      "additionalProperties": false,
      "properties": {
        "version": {"$ref": "#/definitions/version"},
        "hash": {"$ref": "#/definitions/sha256"},
        "written_before_first_score": {"type": "boolean", "const": true},
        "first_score_at": {"$ref": "#/definitions/date"},
        "criteria": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["name", "job_requirement", "anchors"],
            "additionalProperties": false,
            "properties": {
              "name": {"type": "string", "minLength": 2},
              "job_requirement": {"type": "string", "minLength": 5},
              "anchors": {
                "type": "object",
                "required": ["low", "mid", "high"],
                "additionalProperties": false,
                "properties": {
                  "low": {"type": "string", "minLength": 10},
                  "mid": {"type": "string", "minLength": 10},
                  "high": {"type": "string", "minLength": 10}
                }
              }
            }
          }
        }
      }
    },
    "proxy_review": {
      "type": "object",
      "required": ["reviewed_on", "reviewed_by", "proxy_terms_found", "evidence_url"],
      "additionalProperties": false,
      "properties": {
        "reviewed_on": {"$ref": "#/definitions/date"},
        "reviewed_by": {"$ref": "#/definitions/handle"},
        "proxy_terms_found": {"type": "array", "maxItems": 0, "items": {"type": "string"}},
        "evidence_url": {"type": "string", "format": "uri"}
      }
    },
    "calibration": {
      "type": "object",
      "required": ["sample_source", "sample_size", "human_reviewers", "statistic", "threshold", "threshold_set_before_run", "result", "run_url", "passed"],
      "additionalProperties": false,
      "properties": {
        "sample_source": {"type": "string", "const": "real-applicant-pool"},
        "sample_size": {"type": "integer", "minimum": 1},
        "human_reviewers": {"type": "integer", "minimum": 2},
        "statistic": {"type": "string", "enum": ["cohens-kappa", "weighted-kappa", "spearman"]},
        "threshold": {"type": "number", "minimum": -1, "maximum": 1},
        "threshold_set_before_run": {"type": "boolean", "const": true},
        "result": {"type": "number", "minimum": -1, "maximum": 1},
        "run_url": {"type": "string", "format": "uri"},
        "passed": {"type": "boolean"},
        "run_at": {"$ref": "#/definitions/date"}
      }
    },
    "adverse_impact": {
      "type": "object",
      "required": ["self_id_store", "self_id_store_separate_from_scoring", "hold_threshold", "per_stage"],
      "additionalProperties": false,
      "properties": {
        "self_id_store": {"type": "string", "minLength": 2},
        "self_id_store_separate_from_scoring": {"type": "boolean", "const": true},
        "hold_threshold": {"type": "number", "const": 0.8},
        "per_stage": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "required": ["stage", "groups", "min_ratio", "on_hold"],
            "additionalProperties": false,
            "properties": {
              "stage": {"type": "string", "minLength": 2},
              "groups": {
                "type": "array",
                "minItems": 2,
                "items": {
                  "type": "object",
                  "required": ["group", "selection_rate"],
                  "additionalProperties": false,
                  "properties": {
                    "group": {"type": "string", "minLength": 1},
                    "selection_rate": {"type": "number", "minimum": 0, "maximum": 1}
                  }
                }
              },
              "min_ratio": {"type": "number", "minimum": 0, "maximum": 1, "description": "lowest group rate divided by highest group rate"},
              "on_hold": {"type": "boolean"}
            },
            "if": {"properties": {"min_ratio": {"exclusiveMaximum": 0.8}}},
            "then": {"properties": {"on_hold": {"const": true}}}
          }
        },
        "table_url": {"type": "string", "format": "uri"}
      }
    },
    "human_of_record": {
      "type": "object",
      "required": ["auto_reject_filter_present", "decision_carries_role_handle", "reviewer_inputs"],
      "additionalProperties": false,
      "properties": {
        "auto_reject_filter_present": {"type": "boolean", "const": false},
        "decision_carries_role_handle": {"type": "boolean", "const": true},
        "reviewer_inputs": {
          "type": "array",
          "minItems": 2,
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["redacted-document", "score-with-reasons"]}
        },
        "reviewers": {"type": "array", "items": {"$ref": "#/definitions/handle"}}
      }
    },
    "legal": {
      "type": "object",
      "required": ["applicable_law"],
      "additionalProperties": false,
      "properties": {
        "applicable_law": {"type": "string", "enum": ["nyc-ll-144", "illinois-aivi", "colorado-ai-act", "eu-ai-act", "other", "none"]},
        "confirmed_by": {"$ref": "#/definitions/handle"},
        "notice_text_url": {"type": "string", "format": "uri"},
        "notice_lead_business_days": {"type": "integer", "minimum": 0},
        "bias_audit": {
          "type": "object",
          "required": ["conducted_on", "independent", "summary_url"],
          "additionalProperties": false,
          "properties": {
            "conducted_on": {"$ref": "#/definitions/date"},
            "independent": {"type": "boolean", "const": true},
            "summary_url": {"type": "string", "format": "uri"},
            "auditor": {"type": "string"}
          }
        }
      },
      "allOf": [
        {
          "if": {"properties": {"applicable_law": {"const": "none"}}},
          "then": {"required": ["confirmed_by"]},
          "else": {"required": ["notice_text_url", "bias_audit"]}
        },
        {
          "if": {"properties": {"applicable_law": {"const": "nyc-ll-144"}}},
          "then": {"required": ["notice_lead_business_days"], "properties": {"notice_lead_business_days": {"minimum": 10}}}
        }
      ]
    },
    "audit_log": {
      "type": "object",
      "required": ["fields", "retention_months", "queryable_per_candidate"],
      "additionalProperties": false,
      "properties": {
        "fields": {
          "type": "array",
          "minItems": 7,
          "uniqueItems": true,
          "items": {"type": "string", "enum": ["submission_hash", "redacted_text", "model_id", "prompt_hash", "rubric_version", "score_with_reasons", "human_decision"]}
        },
        "retention_months": {"type": "integer", "minimum": 12},
        "retention_basis": {"type": "string"},
        "queryable_per_candidate": {"type": "boolean", "const": true},
        "storage": {"type": "string"}
      }
    },
    "pinned_tuple": {
      "type": "object",
      "required": ["model_id", "prompt_hash", "rubric_version", "redaction_version"],
      "additionalProperties": false,
      "properties": {
        "model_id": {"type": "string", "minLength": 3, "not": {"pattern": "(?i)(^|[-:@/_])latest$"}},
        "prompt_hash": {"$ref": "#/definitions/sha256"},
        "rubric_version": {"$ref": "#/definitions/version"},
        "redaction_version": {"$ref": "#/definitions/version"}
      }
    },
    "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "format": "uri"}}
  }
}

output-contract.example:
{
  "role_title": "Senior backend engineer",
  "candidate_jurisdictions": ["US-NY", "US-CA", "DE"],
  "redaction": {
    "version": "1.3.0",
    "stripped_attributes": ["name", "photo", "email-handle", "date-of-birth-and-age", "graduation-years", "address-below-city", "gender-markers-and-pronouns", "nationality-and-visa-status", "marital-and-parental-status", "protected-class-associations"],
    "unit_tested": true,
    "fixture_set_path": "hiring/redaction/fixtures/",
    "human_sample_inspected_per_release": true,
    "sample_size_per_release": 20
  },
  "rubric": {
    "version": "2.1",
    "hash": "sha256:4c2a9b1e7f3d6a8c0b5e2f9d1a7c3e6b8f0d2a4c6e8b1d3f5a7c9e1b3d5f7a9c",
    "written_before_first_score": true,
    "first_score_at": "2026-02-10",
    "criteria": [
      {"name": "correctness", "job_requirement": "Ships services that pass the integration suite", "anchors": {"low": "Solution fails the provided test cases or does not run", "mid": "Passes the provided tests; misses at least one stated edge case", "high": "Passes provided tests and handles every stated edge case with tests of its own"}},
      {"name": "design clarity", "job_requirement": "Designs modules other engineers can extend", "anchors": {"low": "Single function with mixed concerns; no explanation of trade-offs", "mid": "Reasonable separation; trade-offs partly explained", "high": "Clear module boundaries with the trade-offs and alternatives stated"}}
    ]
  },
  "proxy_review": {
    "reviewed_on": "2026-02-03",
    "reviewed_by": "dei:rkim",
    "proxy_terms_found": [],
    "evidence_url": "https://hr.example.com/reviews/rubric-2.1-proxy-review"
  },
  "calibration": {
    "sample_source": "real-applicant-pool",
    "sample_size": 30,
    "human_reviewers": 2,
    "statistic": "weighted-kappa",
    "threshold": 0.65,
    "threshold_set_before_run": true,
    "result": 0.71,
    "run_url": "https://hr.example.com/calibration/backend-2026-02",
    "passed": true,
    "run_at": "2026-02-07"
  },
  "adverse_impact": {
    "self_id_store": "hris.eeo_self_id",
    "self_id_store_separate_from_scoring": true,
    "hold_threshold": 0.8,
    "per_stage": [
      {"stage": "take-home forwarded to hiring manager", "groups": [{"group": "A", "selection_rate": 0.52}, {"group": "B", "selection_rate": 0.47}, {"group": "C", "selection_rate": 0.49}], "min_ratio": 0.9, "on_hold": false},
      {"stage": "advanced to onsite", "groups": [{"group": "A", "selection_rate": 0.31}, {"group": "B", "selection_rate": 0.27}, {"group": "C", "selection_rate": 0.29}], "min_ratio": 0.87, "on_hold": false}
    ],
    "table_url": "https://hr.example.com/adverse-impact/backend-2026-q1"
  },
  "human_of_record": {
    "auto_reject_filter_present": false,
    "decision_carries_role_handle": true,
    "reviewer_inputs": ["redacted-document", "score-with-reasons"],
    "reviewers": ["em:jdoe", "em:apatel"]
  },
  "legal": {
    "applicable_law": "nyc-ll-144",
    "notice_text_url": "https://careers.example.com/aedt-notice",
    "notice_lead_business_days": 10,
    "bias_audit": {"conducted_on": "2025-11-15", "independent": true, "summary_url": "https://careers.example.com/aedt-bias-audit-2025", "auditor": "Example Audit LLP"}
  },
  "audit_log": {
    "fields": ["submission_hash", "redacted_text", "model_id", "prompt_hash", "rubric_version", "score_with_reasons", "human_decision"],
    "retention_months": 24,
    "retention_basis": "29 CFR 1602.14 one-year floor; company policy two years",
    "queryable_per_candidate": true,
    "storage": "hiring.screen_audit table, candidate_id index"
  },
  "pinned_tuple": {
    "model_id": "claude-sonnet-4-5-20250929",
    "prompt_hash": "sha256:8e1f0a3c5b7d9f2e4a6c8b0d1f3e5a7c9b1d3f5e7a9c2b4d6f8a0c1e3b5d7f9a",
    "rubric_version": "2.1",
    "redaction_version": "1.3.0"
  },
  "evidence": [
    "https://hr.example.com/calibration/backend-2026-02",
    "https://hr.example.com/reviews/rubric-2.1-proxy-review",
    "https://careers.example.com/aedt-bias-audit-2025",
    "https://hr.example.com/adverse-impact/backend-2026-q1"
  ]
}

